import { copyFileSync, existsSync, mkdirSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import tailwindcss from '@tailwindcss/vite';
import vue from '@vitejs/plugin-vue';
import { defineConfig, type Plugin } from 'vite';

const root = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(root, '..');

// The validity bitmap is generated by the Go tooling and is the one artifact
// both implementations must read byte-identically. Keeping a single copy under
// backend/ and copying it here removes any chance of the two drifting.
const VALIDITY_SRC = resolve(repoRoot, 'backend/internal/codec/tables/validity.bin');
const VALIDITY_DEST = resolve(root, 'public/codec/validity.bin');

function validityBitmap(): Plugin {
  return {
    name: 'qrforqa:validity-bitmap',
    buildStart() {
      if (!existsSync(VALIDITY_SRC)) {
        this.error(
          `missing ${VALIDITY_SRC}\nRun \`make vectors\` in the repository root first.`,
        );
      }
      mkdirSync(dirname(VALIDITY_DEST), { recursive: true });
      copyFileSync(VALIDITY_SRC, VALIDITY_DEST);
    },
    configureServer(server) {
      mkdirSync(dirname(VALIDITY_DEST), { recursive: true });
      copyFileSync(VALIDITY_SRC, VALIDITY_DEST);
      server.watcher.add(VALIDITY_SRC);
    },
  };
}

/**
 * Keeps the Go embed directory non-empty.
 *
 * The build output lives in backend/internal/webui/dist, which git ignores
 * except for a committed `.gitkeep`. `go:embed` of a missing directory is a
 * compile error, so a fresh clone needs the directory to exist before anyone
 * runs a frontend build — and `emptyOutDir` would otherwise delete the marker
 * on every build.
 */
function keepEmbedDir(): Plugin {
  const outDir = resolve(repoRoot, 'backend/internal/webui/dist');
  return {
    name: 'qrforqa:keep-embed-dir',
    closeBundle() {
      mkdirSync(outDir, { recursive: true });
      writeFileSync(resolve(outDir, '.gitkeep'), '');
    },
  };
}

export default defineConfig({
  plugins: [vue(), tailwindcss(), validityBitmap(), keepEmbedDir()],
  resolve: {
    alias: {
      '@': resolve(root, 'src'),
    },
  },
  server: {
    port: 5173,
    proxy: {
      '/api': { target: 'http://127.0.0.1:8080', changeOrigin: true },
      '/healthz': { target: 'http://127.0.0.1:8080', changeOrigin: true },
    },
    // The conformance tests read spec/vectors and the Go artifact from the
    // repository root, outside Vite's default serving root.
    fs: { allow: [root, repoRoot] },
  },
  build: {
    // Straight into the Go embed directory, so `go build` picks up the bundle.
    outDir: resolve(repoRoot, 'backend/internal/webui/dist'),
    emptyOutDir: true,
    // Ciphertext is high-entropy and incompressible, so compressing it wastes
    // CPU for no gain; the JS and CSS still benefit.
    chunkSizeWarningLimit: 900,
  },
});
